*{box-sizing:border-box}body{background:#f3f6fb}.verifier-content{padding:20px;flex:1;min-height:0;overflow:hidden;display:flex;flex-direction:column}.page-header-card{background:#fff;border:1px solid #d6dce8;border-radius:12px;padding:18px 20px;margin-bottom:14px;display:flex;justify-content:space-between;align-items:center;gap:14px}.page-header-card h1{margin:0;font-size:24px;color:#111827}.page-header-card p{margin:6px 0 0;font-size:14px;color:#6b7280}.header-actions{display:flex;gap:8px;flex-wrap:wrap}.header-btn,.icon-link{height:42px;border:0;border-radius:10px;font-weight:900;padding:0 14px;display:inline-flex;align-items:center;justify-content:center;gap:7px;cursor:pointer;text-decoration:none}.refresh-main,.icon-link{background:#374151;color:white}.upload-main{background:#168fcb;color:white}.template-main{background:#e5e7eb;color:#111827}.import-result{display:none;margin-bottom:14px;border-radius:10px;padding:10px 12px;font-size:13px;font-weight:800}.toolbar{display:grid;grid-template-columns:1fr 150px 170px 120px auto;gap:10px;margin-bottom:14px;align-items:center}.toolbar input,.toolbar select{height:42px;padding:0 12px;border:1px solid #cbd5e1;border-radius:8px;font-size:14px;background:white}.sheet-card{background:white;border:1px solid #cbd5e1;border-radius:12px;overflow:hidden;flex:1;display:flex;flex-direction:column}.table-scroll{width:100%;overflow:auto;flex:1}.verifier-table{width:100%;min-width:1030px;border-collapse:collapse;font-size:13px}.verifier-table th{background:#dbeafe;color:#111827;font-weight:800;text-align:left;border-bottom:1px solid #b6c3d5;padding:11px 10px;white-space:nowrap;position:sticky;top:0;z-index:3}.verifier-table td{border-bottom:1px solid #e5e7eb;padding:10px;vertical-align:middle;background:#fff;white-space:nowrap}.verifier-table tbody tr:nth-child(even) td{background:#f9fafb}.verifier-table tbody tr:hover td{background:#eef6ff}.row-priority td{background:#fff7ed!important}.row-number{text-align:center;font-weight:800;color:#475569}.client-name{font-weight:800;color:#111827}.muted-small{color:#6b7280;font-size:12px;display:block;margin-top:2px}.queue-number{font-weight:900;color:#1d4ed8}.priority-queue-number{color:#c2410c!important}.priority-label,.category-badge{display:inline-block;padding:3px 8px;border-radius:999px;font-size:11px;font-weight:900;margin-left:6px}.priority-label{background:#fed7aa;color:#9a3412}.category-badge{background:#e5e7eb;color:#374151}.status-badge{display:inline-block;min-width:116px;text-align:center;padding:6px 10px;border-radius:999px;font-size:11px;font-weight:900;text-transform:uppercase}.status-step-2{background:#fef3c7;color:#92400e}.status-called-2{background:#fde68a;color:#78350f}.status-step-3{background:#dbeafe;color:#1e40af}.status-called-3{background:#bfdbfe;color:#1e3a8a}.status-paid{background:#dcfce7;color:#166534}.status-cancelled{background:#fee2e2;color:#991b1b}.status-none{background:#e5e7eb;color:#374151}.action-group{display:flex;gap:6px;justify-content:center}.action-group form{margin:0}.icon-btn{width:36px;height:36px;border:none;border-radius:8px;color:white;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;text-decoration:none}.icon-btn .material-icons{font-size:19px}.btn-regular{background:#16a34a}.btn-priority{background:#dc2626}.btn-regenerate{background:#9ca3af}.btn-view{background:#2563eb}.btn-remove{background:#991b1b}.icon-btn:disabled{background:#9ca3af;cursor:not-allowed}.footer-note{padding:10px 12px;font-size:12px;color:#6b7280;background:#f9fafb;border-top:1px solid #d1d5db;display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}.pagination{display:flex;align-items:center;justify-content:center;gap:8px;padding:10px 12px;border-top:1px solid #d1d5db;background:#fff}.page-btn{height:34px;min-width:34px;border:1px solid #cbd5e1;border-radius:7px;background:white;cursor:pointer;font-weight:800}.page-btn:disabled{opacity:.45}.page-info{font-size:13px;color:#475569;font-weight:700}.empty-state,.loading-text{text-align:center;padding:22px;color:#6b7280;font-weight:800}.modal-overlay{display:none;position:fixed;inset:0;background:rgba(15,23,42,.55);z-index:9999;justify-content:center;align-items:center;padding:20px}.modal-box{width:680px;max-width:96%;background:#fff;border-radius:14px;padding:24px;box-shadow:0 14px 40px rgba(0,0,0,.25)}.details-box{width:760px}.modal-box h2{margin:0;color:#111827;font-size:22px}.modal-box p{margin:8px 0 20px;color:#4b5563;font-size:14px}.type-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:14px}.type-btn{border:0;border-radius:12px;padding:13px 10px;color:white;font-weight:1000;cursor:pointer;text-align:center}.type-btn span{display:block;font-size:12px;opacity:.9}.blue{background:#0b5ed7}.orange{background:#f97316}.modal-cancel{width:100%;height:42px;border:none;border-radius:10px;background:#e5e7eb;color:#111827;font-weight:900;cursor:pointer}.details-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}.detail-item{background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;padding:10px}.detail-item span{display:block;font-size:11px;color:#64748b;font-weight:800;text-transform:uppercase;margin-bottom:4px}.detail-item strong{display:block;color:#111827;font-size:13px;word-break:break-word}@media(max-width:1000px){.toolbar{grid-template-columns:1fr 1fr}.type-grid{grid-template-columns:1fr 1fr}.verifier-table{min-width:980px}}@media(max-width:700px){.page-header-card{flex-direction:column;align-items:flex-start}.toolbar,.details-grid,.type-grid{grid-template-columns:1fr}.verifier-content{overflow:visible}.sheet-card{min-height:520px}}
</style></head><body><div class="app"><main class="main"><section class="verifier-content"><div class="page-header-card"><div><h1>Verify [Step 1]</h1><p>Search beneficiary records, import CSV/Excel data, view details, and generate assistance-specific queue numbers.</p></div><div class="header-actions"><button type="button" class="header-btn template-main" onclick="downloadTemplate()"><span class="material-icons">download</span>CSV Template</button><button type="button" class="header-btn upload-main" onclick="chooseFile()"><span class="material-icons">file_upload</span>Upload File</button><button type="button" class="header-btn refresh-main" onclick="manualRefresh()"><span class="material-icons">refresh</span>Refresh</button></div></div><input type="file" id="importFile" accept=".csv,.xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" hidden><div class="import-result" id="importResult"></div><div class="toolbar"><input type="text" id="searchInput" placeholder="Search name, queue, barangay, LGU..."><select id="typeFilter"><option value="all">All Types</option><option value="priority">PRIO Only</option><option value="regular">Regular Only</option><option value="none">No Queue</option></select><select id="statusFilter"><option value="all">All Status</option><option value="WAITING_STEP_2">Waiting Step 2</option><option value="CALLED_STEP_2">Called Step 2</option><option value="WAITING_STEP_3">Waiting Step 3</option><option value="CALLED_STEP_3">Called Step 3</option><option value="PAID">Paid</option><option value="none">No Queue</option></select><select id="rowsPerPage"><option value="10">10 rows</option><option value="25" selected>25 rows</option><option value="50">50 rows</option><option value="100">100 rows</option></select><button type="button" class="icon-link" onclick="manualRefresh()" title="Refresh"><span class="material-icons">refresh</span></button></div><div class="sheet-card"><div class="table-scroll"><table class="verifier-table"><thead><tr><th style="width:55px;text-align:center;">#</th><th style="width:135px;">Queue No.</th><th>Name</th><th>Barangay</th><th style="width:70px;">Age</th><th style="width:70px;">Sex</th><th>LGU</th><th style="width:145px;">Status</th><th style="width:220px;text-align:center;">Actions</th></tr></thead><tbody id="beneficiaryRows"><tr><td colspan="9" class="loading-text">Loading beneficiaries...</td></tr></tbody></table></div><div class="pagination" id="paginationControls"></div><div class="footer-note"><span id="recordInfo">Showing records...</span><span id="lastUpdated">Last updated: --</span></div></div></section></main><?php include('sidebar.php'); ?></div>
<div id="generateModal" class="modal-overlay"><div class="modal-box"><h2>Choose Assistance Type</h2><p>Generate a regular queue using the selected assistance prefix.</p><form id="generateForm" method="POST" action="../api/generate_regular_qn.php"><input type="hidden" name="beneficiary_id" id="genBeneficiaryId"><input type="hidden" name="assistance_prefix" id="genPrefix"><div class="type-grid" id="generateTypeGrid"></div><button type="button" class="modal-cancel" onclick="closeGenerateModal()">Cancel</button></form></div></div>
<div id="regenerateModal" class="modal-overlay"><div class="modal-box"><h2>Choose New Queue Type</h2><p>Regenerate the current queue using an assistance prefix or PRIO.</p><form id="regenerateForm" method="POST" action="../api/regenerate_qn.php"><input type="hidden" name="beneficiary_id" id="regenBeneficiaryId"><input type="hidden" name="assistance_prefix" id="regenPrefix"><div class="type-grid" id="regenerateTypeGrid"></div><button type="button" class="modal-cancel" onclick="closeRegenerateModal()">Cancel</button></form></div></div>
<div id="detailsModal" class="modal-overlay"><div class="modal-box details-box"><h2>Beneficiary Details</h2><p>Complete record view without cluttering the main table.</p><div class="details-grid" id="detailsGrid"></div><button type="button" class="modal-cancel" onclick="closeDetailsModal()">Close</button></div></div>
<script>
const ASSIST=[['MEDI','Medical'],['FNRL','Funeral'],['EDUC','Educational'],['TRAN','Transportation'],['MTRL','Material'],['FDAS','Food'],['CRAS','Cash Relief']],ALL_TYPES=[...ASSIST,['PRIO','Priority']];
const searchInput=document.getElementById('searchInput'),typeFilter=document.getElementById('typeFilter'),statusFilter=document.getElementById('statusFilter'),rowsPerPage=document.getElementById('rowsPerPage'),tableBody=document.getElementById('beneficiaryRows'),lastUpdated=document.getElementById('lastUpdated'),recordInfo=document.getElementById('recordInfo'),paginationControls=document.getElementById('paginationControls'),importFile=document.getElementById('importFile'),importResult=document.getElementById('importResult');let beneficiaries=[],currentPage=1,selectedImportFile=null,isLoading=false;
function escapeHTML(v){if(v===null||v===undefined)return'';return String(v).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;')}function displayStatus(s){return {'WAITING_STEP_2':'Waiting Step 2','CALLED_STEP_2':'Called Step 2','WAITING_STEP_3':'Waiting Step 3','CALLED_STEP_3':'Called Step 3','PAID':'Paid','CANCELLED':'Cancelled'}[s]||'No Queue'}function statusClass(s){return {'WAITING_STEP_2':'status-step-2','CALLED_STEP_2':'status-called-2','WAITING_STEP_3':'status-step-3','CALLED_STEP_3':'status-called-3','PAID':'status-paid','CANCELLED':'status-cancelled'}[s]||'status-none'}function getFullName(r){const m=r.middle_name?' '+r.middle_name:'',e=r.ext_name?' '+r.ext_name:'';return `${r.last_name||''}, ${r.first_name||''}${m}${e}`.trim()}function getCategory(r){if(parseInt(r.is_pwd||r.sms_opt_in||0)===1)return'PWD';if(parseInt(r.is_pregnant||0)===1)return'Pregnant';if(parseInt(r.age||0)>=60)return'Senior';return'Regular'}function getFilteredRows(){const q=searchInput.value.toLowerCase().trim(),ty=typeFilter.value,st=statusFilter.value;return beneficiaries.filter(r=>{const has=r.queue_number&&r.queue_number!=='';const text=[r.queue_number,r.last_name,r.first_name,r.middle_name,r.ext_name,r.barangay,r.city_municipality,r.lgu,r.contact_number,r.beneficiary_code].join(' ').toLowerCase();if(q&&!text.includes(q))return false;if(ty==='priority'&&r.queue_type!=='priority')return false;if(ty==='regular'&&r.queue_type!=='regular')return false;if(ty==='none'&&has)return false;if(st==='none'&&has)return false;if(st!=='all'&&st!=='none'&&r.workflow_status!==st)return false;return true})}
function renderPagination(total,pages){paginationControls.innerHTML=total?`<button class="page-btn" onclick="goToPage(1)" ${currentPage===1?'disabled':''}>«</button><button class="page-btn" onclick="goToPage(${currentPage-1})" ${currentPage===1?'disabled':''}>‹</button><span class="page-info">Page ${currentPage} of ${pages}</span><button class="page-btn" onclick="goToPage(${currentPage+1})" ${currentPage===pages?'disabled':''}>›</button><button class="page-btn" onclick="goToPage(${pages})" ${currentPage===pages?'disabled':''}>»</button>`:''}function goToPage(page){const f=getFilteredRows(),per=parseInt(rowsPerPage.value,10),pages=Math.max(1,Math.ceil(f.length/per));currentPage=Math.min(Math.max(1,page),pages);renderTable()}
function renderTable(){const filtered=getFilteredRows(),per=parseInt(rowsPerPage.value,10),pages=Math.max(1,Math.ceil(filtered.length/per));if(currentPage>pages)currentPage=pages;const start=(currentPage-1)*per,pageRows=filtered.slice(start,start+per);if(!pageRows.length){tableBody.innerHTML='<tr><td colspan="9" class="empty-state">No beneficiaries found.</td></tr>';recordInfo.innerText=`Showing 0 of ${beneficiaries.length} records`;renderPagination(0,1);return}let html='';pageRows.forEach((r,i)=>{const has=r.queue_number&&r.queue_number!=='';const isP=r.queue_type==='priority';const cat=getCategory(r);html+=`<tr class="${isP?'row-priority':''}"><td class="row-number">${start+i+1}</td><td class="queue-number ${isP?'priority-queue-number':''}">${has?escapeHTML(r.queue_number)+(isP?'<span class="priority-label">PRIO</span>':''):'Not generated'}</td><td><span class="client-name">${escapeHTML(getFullName(r))}</span><span class="category-badge">${cat}</span><span class="muted-small">${escapeHTML(r.beneficiary_code||'No code')}</span></td><td>${escapeHTML(r.barangay)}</td><td>${escapeHTML(r.age)}</td><td>${escapeHTML(r.sex)}</td><td>${escapeHTML(r.lgu)}</td><td><span class="status-badge ${statusClass(r.workflow_status)}">${displayStatus(r.workflow_status)}</span></td><td><div class="action-group"><button type="button" class="icon-btn btn-view" title="View Details" onclick="openDetailsModal('${escapeHTML(r.id)}')"><span class="material-icons">visibility</span></button><button type="button" class="icon-btn btn-regular" title="Generate Regular Queue" onclick="openGenerateModal('${escapeHTML(r.id)}')" ${has?'disabled':''}><span class="material-icons">add_circle</span></button><form method="POST" action="../api/generate_priority_qn.php"><input type="hidden" name="beneficiary_id" value="${escapeHTML(r.id)}"><button type="submit" class="icon-btn btn-priority" title="Generate PRIO" ${has?'disabled':''}><span class="material-icons">priority_high</span></button></form><button type="button" class="icon-btn btn-regenerate" title="Regenerate Queue" onclick="openRegenerateModal('${escapeHTML(r.id)}')" ${!has?'disabled':''}><span class="material-icons">sync</span></button><form method="POST" action="../api/remove_beneficiary.php"><input type="hidden" name="beneficiary_id" value="${escapeHTML(r.id)}"><input type="hidden" name="redirect" value="../staff/verifier.php"><button type="submit" class="icon-btn btn-remove" title="Remove Beneficiary"><span class="material-icons">delete</span></button></form></div></td></tr>`});tableBody.innerHTML=html;recordInfo.innerText=`Showing ${start+1}-${Math.min(start+per,filtered.length)} of ${filtered.length} filtered records (${beneficiaries.length} total)`;renderPagination(filtered.length,pages)}
function buildTypeGrid(id,types,fn){document.getElementById(id).innerHTML=types.map(t=>`<button type="button" class="type-btn ${t[0]==='PRIO'?'orange':'blue'}" onclick="${fn}('${t[0]}')">${t[0]}<span>${t[1]}</span></button>`).join('')}buildTypeGrid('generateTypeGrid',ASSIST,'submitGenerate');buildTypeGrid('regenerateTypeGrid',ALL_TYPES,'submitRegenerate');
function openGenerateModal(id){document.getElementById('genBeneficiaryId').value=id;document.getElementById('genPrefix').value='';document.getElementById('generateModal').style.display='flex'}function closeGenerateModal(){document.getElementById('generateModal').style.display='none'}function submitGenerate(prefix){document.getElementById('genPrefix').value=prefix;document.getElementById('generateForm').submit()}function openRegenerateModal(id){document.getElementById('regenBeneficiaryId').value=id;document.getElementById('regenPrefix').value='';document.getElementById('regenerateModal').style.display='flex'}function closeRegenerateModal(){document.getElementById('regenerateModal').style.display='none'}function submitRegenerate(prefix){document.getElementById('regenPrefix').value=prefix;document.getElementById('regenerateForm').submit()}
function openDetailsModal(id){const r=beneficiaries.find(x=>String(x.id)===String(id));if(!r)return;const birthday=r.birthday_month&&r.birthday_day&&r.birthday_year?`${r.birthday_month}/${r.birthday_day}/${r.birthday_year}`:'';const address=[r.barangay,r.city_municipality,r.province,r.region].filter(Boolean).join(', ');const details=[['Category',getCategory(r)],['Beneficiary Code',r.beneficiary_code],['Queue Number',r.queue_number||'Not generated'],['Queue Type',r.queue_type||'None'],['Status',displayStatus(r.workflow_status)],['Last Name',r.last_name],['First Name',r.first_name],['Middle Name',r.middle_name],['Ext. Name',r.ext_name],['Region',r.region],['Province',r.province],['City/Municipality',r.city_municipality],['Barangay',r.barangay],['Contact Number',r.contact_number],['Birthday',birthday],['Age',r.age],['Sex',r.sex],['LGU',r.lgu],['Address',address||'-']];document.getElementById('detailsGrid').innerHTML=details.map(x=>`<div class="detail-item"><span>${escapeHTML(x[0])}</span><strong>${escapeHTML(x[1]||'-')}</strong></div>`).join('');document.getElementById('detailsModal').style.display='flex'}function closeDetailsModal(){document.getElementById('detailsModal').style.display='none'}['generateModal','regenerateModal','detailsModal'].forEach(id=>document.getElementById(id).addEventListener('click',function(e){if(e.target===this)this.style.display='none'}));
async function loadVerifierData(){if(isLoading)return;isLoading=true;try{const res=await fetch('../api/verifier_data.php?ts='+Date.now(),{cache:'no-store'});const data=await res.json();if(!data.success){tableBody.innerHTML=`<tr><td colspan="9" class="empty-state">${escapeHTML(data.message)}</td></tr>`;return}beneficiaries=data.beneficiaries;renderTable();lastUpdated.innerText='Last updated: '+new Date().toLocaleTimeString()}catch(e){console.error(e);tableBody.innerHTML='<tr><td colspan="9" class="empty-state">Failed to load data.</td></tr>'}finally{isLoading=false}}async function manualRefresh(){isLoading=false;currentPage=1;await loadVerifierData()}
function chooseFile(){importFile.click()}function showImportResult(msg,ok=true){importResult.style.display='block';importResult.style.borderColor=ok?'#86efac':'#fecaca';importResult.style.background=ok?'#f0fdf4':'#fef2f2';importResult.style.color=ok?'#166534':'#991b1b';importResult.innerHTML=msg}async function uploadImportFile(file){if(!file)return;const lower=file.name.toLowerCase();if(!lower.endsWith('.csv')&&!lower.endsWith('.xlsx')){showImportResult('Please upload CSV or Excel .xlsx file only.',false);return}showImportResult('Importing '+escapeHTML(file.name)+', please wait...',true);const fd=new FormData();fd.append('import_file',file);try{const res=await fetch('../api/import_beneficiaries.php',{method:'POST',body:fd});const data=await res.json();if(!data.success){showImportResult(escapeHTML(data.message||'Import failed.'),false);return}showImportResult(`Imported: ${data.inserted||0} | Duplicates skipped: ${data.duplicates||0} | Failed rows: ${data.failed||0}`,true);importFile.value='';currentPage=1;loadVerifierData()}catch(e){console.error(e);showImportResult('Import failed. Please check the file format.',false)}}importFile.addEventListener('change',()=>uploadImportFile(importFile.files[0]));function csvEscape(v){v=String(v==null?'':v);return /[",\n]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v}function downloadTemplate(){const row=['last_name','first_name','middle_name','ext_name','birthday','age','sex','contact_number','id_presented','household_id','region','province','city_municipality','barangay','lgu','program_type','pwd','pregnant'];const sample=['Dela Cruz','Juan','Santos','','01/15/1985','40','Male','09170000001','PhilSys ID','HH-0000000001','MIMAROPA','Oriental Mindoro','Calapan City','Barangay 1','Calapan City','Medical Assistance','No','No'];const csv=row.join(',')+'\n'+sample.map(csvEscape).join(',')+'\n';const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='beneficiary_import_template.csv';a.click();URL.revokeObjectURL(url)}[searchInput,typeFilter,statusFilter,rowsPerPage].forEach(e=>{e.addEventListener('input',()=>{currentPage=1;renderTable()});e.addEventListener('change',()=>{currentPage=1;renderTable()})});manualRefresh();
</script><script src="../assets/verifier_helpers.js"></script><script src="../assets/import_progress.js"></script></body></html>